create table tenants (id uuid primary key, company_name varchar(200) not null, country varchar(100) not null, timezone varchar(80) not null default 'UTC', default_currency varchar(3) not null default 'USD', plan varchar(20) not null default 'FREE', status varchar(20) not null default 'ACTIVE', created_at timestamptz not null, updated_at timestamptz not null);
create table users (id uuid primary key, tenant_id uuid not null references tenants(id), full_name varchar(150) not null, email varchar(255) not null unique, password_hash varchar(255) not null, role varchar(20) not null, status varchar(20) not null, last_login_at timestamptz, created_at timestamptz not null, updated_at timestamptz not null);
create table customers (id uuid primary key, tenant_id uuid not null references tenants(id), customer_code varchar(40) not null, company_name varchar(200) not null, customer_type varchar(30) not null, country varchar(100) not null, gstin varchar(40), iec varchar(40), status varchar(20) not null, sales_owner_user_id uuid references users(id), created_at timestamptz not null, updated_at timestamptz not null, unique(tenant_id,customer_code));
create table customer_contacts (id uuid primary key, tenant_id uuid not null references tenants(id), customer_id uuid not null references customers(id), name varchar(150) not null, email varchar(255) not null, phone varchar(50) not null, designation varchar(100), is_primary boolean not null, created_at timestamptz not null, updated_at timestamptz not null);
create table customer_addresses (id uuid primary key, tenant_id uuid not null references tenants(id), customer_id uuid not null references customers(id), address_type varchar(30) not null, line1 varchar(255) not null, line2 varchar(255), city varchar(100) not null, state varchar(100), postal_code varchar(30), country varchar(100) not null, created_at timestamptz not null, updated_at timestamptz not null);
create table enquiries (id uuid primary key, tenant_id uuid not null references tenants(id), enquiry_code varchar(40) not null, customer_id uuid not null references customers(id), contact_id uuid references customer_contacts(id), mode varchar(20) not null, origin varchar(200) not null, destination varchar(200) not null, port_of_loading varchar(200), port_of_discharge varchar(200), airport_of_origin varchar(200), airport_of_destination varchar(200), commodity varchar(200) not null, gross_weight numeric(14,3), weight_unit varchar(20), volume numeric(14,3), volume_unit varchar(20), package_count integer, ready_date date, incoterm varchar(30), cargo_type varchar(30), container_type varchar(30), container_quantity integer, pickup_required boolean not null default false, export_customs_required boolean not null default false, insurance_required boolean not null default false, destination_delivery_required boolean not null default false, notes text, status varchar(30) not null, created_by uuid not null references users(id), created_at timestamptz not null, updated_at timestamptz not null, unique(tenant_id,enquiry_code));
create table quotations (id uuid primary key, tenant_id uuid not null references tenants(id), quotation_number varchar(40) not null, enquiry_id uuid not null references enquiries(id), customer_id uuid not null references customers(id), currency varchar(3) not null, transit_time_text varchar(200), valid_until date not null, terms_and_conditions text not null, notes text, total_amount numeric(14,2) not null, status varchar(20) not null, created_by uuid not null references users(id), sent_at timestamptz, created_at timestamptz not null, updated_at timestamptz not null, version bigint not null default 0, unique(tenant_id,quotation_number));
create table quotation_lines (id uuid primary key, tenant_id uuid not null references tenants(id), quotation_id uuid not null references quotations(id) on delete cascade, description varchar(255) not null, quantity numeric(12,2) not null, unit_price numeric(14,2) not null, amount numeric(14,2) not null, sort_order integer not null);
create table quotation_email_logs (id uuid primary key, tenant_id uuid not null references tenants(id), quotation_id uuid not null references quotations(id), recipient varchar(255) not null, cc varchar(255), subject varchar(255) not null, sent_by uuid not null references users(id), status varchar(20) not null, error_message text, sent_at timestamptz not null);
create index idx_users_tenant on users(tenant_id);
create index idx_customers_tenant_name on customers(tenant_id,company_name);
create index idx_contacts_tenant_customer on customer_contacts(tenant_id,customer_id);
create index idx_addresses_tenant_customer on customer_addresses(tenant_id,customer_id);
create index idx_enquiries_tenant_created on enquiries(tenant_id,created_at desc);
create index idx_enquiries_customer on enquiries(tenant_id,customer_id);
create index idx_quotations_tenant_created on quotations(tenant_id,created_at desc);
create index idx_quotations_customer on quotations(tenant_id,customer_id);
create index idx_quotation_lines_tenant on quotation_lines(tenant_id,quotation_id);
create index idx_email_logs_tenant on quotation_email_logs(tenant_id,quotation_id);
